// ===== Match Kalshi Teams (v3 — two-way market model, MLB) =====
// MLB moneyline markets on Kalshi are a straight two-way contract
// (Home-yes vs Away-yes) — no draw leg like soccer. This version
// mirrors the Soccer v3 fix: robust team-name matching (with MLB
// aliases + synonym groups) and correctly labeled home/away legs
// instead of blindly grabbing whichever leg matches home_team.

const items    = $input.all();
const awayTeam = $('Parse Teams').item.json.away_team || '';
const homeTeam = $('Parse Teams').item.json.home_team || '';

const normalize = s => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9 -]/g, ' ')
  .replace(/-/g, ' ').replace(/\s+/g, ' ').trim();

const SYNONYM_GROUPS = [
  ['new york yankees', 'yankees', 'ny yankees'],
  ['new york mets', 'mets', 'ny mets'],
  ['chicago white sox', 'white sox', 'cws'],
  ['chicago cubs', 'cubs'],
  ['los angeles dodgers', 'dodgers', 'la dodgers'],
  ['los angeles angels', 'angels', 'la angels'],
  ['san francisco giants', 'giants', 'sf giants'],
  ['san diego padres', 'padres'],
  ['st. louis cardinals', 'cardinals', 'stl'],
  ['kansas city royals', 'royals'],
  ['boston red sox', 'red sox'],
  ['tampa bay rays', 'rays'],
  ['toronto blue jays', 'blue jays', 'jays'],
  ['minnesota twins', 'twins'],
  ['cleveland guardians', 'guardians'],
  ['detroit tigers', 'tigers'],
  ['milwaukee brewers', 'brewers'],
  ['cincinnati reds', 'reds'],
  ['pittsburgh pirates', 'pirates'],
  ['atlanta braves', 'braves'],
  ['miami marlins', 'marlins'],
  ['philadelphia phillies', 'phillies'],
  ['washington nationals', 'nationals', 'nats'],
  ['arizona diamondbacks', 'diamondbacks', 'dbacks'],
  ['colorado rockies', 'rockies'],
  ['seattle mariners', 'mariners'],
  ['oakland athletics', 'athletics', 'as'],
  ['texas rangers', 'rangers'],
  ['houston astros', 'astros'],
  ['baltimore orioles', 'orioles'],
];

const findGroup = n => {
  if (!n) return null;
  for (const g of SYNONYM_GROUPS) {
    if (g.some(p => p === n || n.includes(p) || p.includes(n))) return g;
  }
  return null;
};

const STOP = ['the','and','for','with','city','team','state'];
const sigWords = n => n.split(' ').filter(w => w.length > 3 && !STOP.includes(w));

const titleMatchesTeam = (title, team) => {
  const ti = normalize(title), t = normalize(team);
  if (!t || !ti) return false;
  if (ti.includes(t)) return true;
  const g = findGroup(t);
  if (g && g.some(p => ti.includes(p))) return true;
  return sigWords(t).some(w => ti.includes(w));
};

const subMatchesTeam = (sub, team) => {
  const s = normalize(sub), t = normalize(team);
  if (!s || !t) return false;
  if (s.includes(t) || t.includes(s)) return true;
  const g = findGroup(t);
  if (g && g.some(p => s.includes(p))) return true;
  return sigWords(t).some(w => s.includes(w));
};

let kalshiEdge = null;

try {
  const cacheRow = items[0]?.json;
  const markets  = cacheRow?.data?.markets;

  if (Array.isArray(markets) && markets.length > 0 && homeTeam && homeTeam !== 'General') {

    const gameMarkets = markets.filter(m =>
      titleMatchesTeam(m.title, awayTeam) && titleMatchesTeam(m.title, homeTeam)
    );

    if (gameMarkets.length > 0) {
      // Two-way market: classify each leg as home-win or away-win —
      // NOT yes/no of a single binary contract.
      const homeLeg = gameMarkets.find(m => subMatchesTeam(m.yes_sub_title, homeTeam));
      const awayLeg = gameMarkets.find(m => subMatchesTeam(m.yes_sub_title, awayTeam));

      const legPct = leg => {
        if (!leg) return null;
        const yd = leg.yes_bid_dollars ?? leg.last_price_dollars ?? null;
        return yd !== null ? (parseFloat(yd) * 100) : null;
      };
      const legVol = leg => leg ? parseFloat(leg.volume_fp ?? 0) : 0;

      const homePct = legPct(homeLeg), awayPct = legPct(awayLeg);

      if (homePct !== null || awayPct !== null) {
        const totalVolume = legVol(homeLeg) + legVol(awayLeg);
        kalshiEdge = {
          market:            gameMarkets[0].title,
          home_team:         homeTeam,
          away_team:         awayTeam,
          home_implied_pct:  homePct !== null ? homePct.toFixed(1) : 'n/a',
          away_implied_pct:  awayPct !== null ? awayPct.toFixed(1) : 'n/a',
          volume:            totalVolume.toFixed(0),
        };
      }
    }
  }
} catch(e) {}

return [{
  json: {
    ...(items[0]?.json || {}),
    kalshi_edge:      kalshiEdge,
    kalshi_available: kalshiEdge !== null,
  }
}];

const items = $input.all();
const away  = $('Parse Teams').item.json.away_team || '';
const home  = $('Parse Teams').item.json.home_team || '';

// Word-level team name matching (same logic as Match Kalshi Teams)
const matchesTeam = (name, team) => {
  if (!name || !team) return false;
  const n = name.toLowerCase();
  const t = team.toLowerCase();
  if (n.includes(t) || t.includes(n)) return true;
  const words = t.split(/\s+/).filter(w =>
    w.length > 3 &&
    !['the','and','for','with','city','team','state'].includes(w)
  );
  return words.some(w => n.includes(w));
};

const espnData = items[0]?.json || {};
const events   = espnData.events || [];

// Find the single event that has both requested teams as competitors
const matchedEvent = events.find(event => {
  const competitors = event.competitions?.[0]?.competitors || [];
  const names = competitors.map(c =>
    c.team?.displayName || c.team?.shortDisplayName || c.team?.name || ''
  );
  return names.some(n => matchesTeam(n, away)) &&
         names.some(n => matchesTeam(n, home));
});

return [{
  json: {
    ...espnData,
    events:      matchedEvent ? [matchedEvent] : [],
    filteredGame: matchedEvent ? (matchedEvent.name || (away + ' vs ' + home)) : null,
    gameFound:   !!matchedEvent,
    gameNote:    matchedEvent
      ? ('Matched: ' + matchedEvent.name)
      : ('Game not found in ESPN data for ' + away + ' vs ' + home),
  }
}];

const KALSHI_PREFIXES = ['Reg Time:', 'Total Goals:', 'Match Winner:', 'Moneyline:', 'To Win:', 'Winner:', 'Result:'];

function stripPrefix(s) {
  let clean = (s || '').trim();
  for (const prefix of KALSHI_PREFIXES) {
    const re = new RegExp('^' + prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*', 'i');
    if (re.test(clean)) {
      clean = clean.replace(re, '').trim();
      break;
    }
  }
  return clean;
}

