const items = $input.all();
const away  = $('Parse Teams').item.json.away_team || '';
const home  = $('Parse Teams').item.json.home_team || '';

const matchesTeam = (name, team) => {
  if (!name || !team) return false;
  const n = name.toLowerCase();
  const t = team.toLowerCase();
  if (n.includes(t) || t.includes(n)) return true;
  const words = t.split(/\s+/).filter(w =>
    w.length > 3 &&
    !['the','and','for','with','city','team','state'].includes(w)
  );
  return words.some(w => n.includes(w));
};

const scheduleData = items[0]?.json || {};
const allGames = (scheduleData.dates || []).flatMap(d => d.games || []);

const matchedGame = allGames.find(g => {
  const awayName = g.teams?.away?.team?.name || '';
  const homeName = g.teams?.home?.team?.name || '';
  return matchesTeam(awayName, away) && matchesTeam(homeName, home);
});

const result = matchedGame ? {
  gamePk:            matchedGame.gamePk,
  gameDate:          matchedGame.gameDate,
  gameStatus:        matchedGame.status?.detailedState,
  away_team_id:      matchedGame.teams?.away?.team?.id,
  away_team_name:    matchedGame.teams?.away?.team?.name,
  away_record:       matchedGame.teams?.away?.leagueRecord,
  away_probable:     matchedGame.teams?.away?.probablePitcher || null,
  home_team_id:      matchedGame.teams?.home?.team?.id,
  home_team_name:    matchedGame.teams?.home?.team?.name,
  home_record:       matchedGame.teams?.home?.leagueRecord,
  home_probable:     matchedGame.teams?.home?.probablePitcher || null,
  venue_name:        matchedGame.venue?.name || matchedGame.teams?.home?.team?.venue?.name || null,
} : null;

return [{
  json: {
    ...scheduleData,
    fixture:        result,
    fixtureFound:   !!result,
    fixtureNote:    result ? ('Matched gamePk ' + result.gamePk) : ('No MLB Stats API game found for ' + away + ' vs ' + home),
  }
}];

// Note: MLB Stats API has no dedicated /injuries endpoint (returns 404).
// Proxy: scan /transactions for IL placements/activations in the last 30 days,
// keep only each player's MOST RECENT move, and only report players whose
// latest move was a placement (not an activation, which means they're back).
//
// Position filtering: the roster/people endpoints only tag pitchers with the
// generic position "P" (no RP/SP/CP distinction), so a pitcher's role is
// classified from their season stats: gamesStarted === 0 means reliever/closer,
// gamesStarted > 0 means starter. Position players (C/1B/2B/3B/SS/LF/CF/RF/DH)
// are excluded from the bullpen count outright via primaryPosition.
const fixture = $('MLB Match Fixture').item.json.fixture;

if (!fixture) {
  return [{ json: { injuries: [], injuriesNote: 'No fixture matched — skipping injury lookup', home_bullpen_out: [], away_bullpen_out: [] } }];
}

const now   = new Date();
const start = new Date(now.getTime() - 30 * 86400 * 1000).toISOString().slice(0, 10);
const end   = now.toISOString().slice(0, 10);
const url   = 'https://statsapi.mlb.com/api/v1/transactions?sportId=1&startDate=' + start + '&endDate=' + end;
const season = now.getFullYear();

const POSITION_PLAYER_ABBRS = ['C','1B','2B','3B','SS','LF','CF','RF','DH','OF','IF'];

const classifyPlayer = async personId => {
  try {
    const person = await this.helpers.httpRequest({ url: 'https://statsapi.mlb.com/api/v1/people/' + personId, method: 'GET', json: true });
    const posAbbr = person.people?.[0]?.primaryPosition?.abbreviation;

    if (posAbbr && POSITION_PLAYER_ABBRS.includes(posAbbr)) {
      return { role: 'position player', posAbbr };
    }

    // Pitcher — determine starter vs reliever from season games-started
    const statsUrl = 'https://statsapi.mlb.com/api/v1/people/' + personId + '/stats?stats=season&group=pitching&season=' + season;
    const stats = await this.helpers.httpRequest({ url: statsUrl, method: 'GET', json: true });
    const split = stats.stats?.[0]?.splits?.[0]?.stat;

    if (!split) return { role: 'pitcher (role unknown — no season stats)', posAbbr: posAbbr || 'P' };

    const isReliever = (split.gamesStarted || 0) === 0;
    return {
      role: isReliever ? ((split.saves || 0) > 0 ? 'CP' : 'RP') : 'SP',
      posAbbr: posAbbr || 'P',
    };
  } catch (e) {
    return { role: 'unknown', posAbbr: null };
  }
};

try {
  const data = await this.helpers.httpRequest({ url, method: 'GET', json: true });
  const tx = data.transactions || [];

  const ilMoves = tx.filter(t => {
    const desc = (t.description || '').toLowerCase();
    return desc.includes('injured list') || desc.includes('il ');
  });

  const teamIds = [fixture.home_team_id, fixture.away_team_id];
  const relevant = ilMoves.filter(t => teamIds.includes(t.toTeam?.id) || teamIds.includes(t.fromTeam?.id));

  // Sort most-recent-first so the dedup below keeps each player's LATEST status
  relevant.sort((a, b) => new Date(b.date) - new Date(a.date));

  const seen = new Set();
  const placements = [];
  for (const t of relevant) {
    const personId = t.person?.id;
    if (personId && seen.has(personId)) continue;
    if (personId) seen.add(personId);

    const desc = (t.description || '').toLowerCase();
    const isActivation = desc.includes('activated') || desc.includes('reinstated');
    if (isActivation) continue; // latest move means they're off the IL now — not currently injured

    placements.push({
      personId,
      player:      t.person?.fullName,
      team:        t.toTeam?.name || t.fromTeam?.name,
      teamId:      t.toTeam?.id || t.fromTeam?.id,
      date:        t.date,
      description: t.description,
    });
  }

  const classifications = await Promise.all(placements.map(p => p.personId ? classifyPlayer(p.personId) : { role: 'unknown', posAbbr: null }));
  const injuries = placements.map((p, i) => ({ ...p, role: classifications[i].role, posAbbr: classifications[i].posAbbr }));

  const bullpenOut = teamId => injuries.filter(i => i.teamId === teamId && (i.role === 'RP' || i.role === 'CP'));
  const home_bullpen_out = bullpenOut(fixture.home_team_id).map(i => i.player + ' (' + i.role + ')');
  const away_bullpen_out = bullpenOut(fixture.away_team_id).map(i => i.player + ' (' + i.role + ')');

  return [{
    json: {
      injuries,
      injuriesNote: injuries.length ? 'Found ' + injuries.length + ' players currently on the IL' : 'No current IL players found for either team',
      home_bullpen_out,
      away_bullpen_out,
    }
  }];
} catch (e) {
  return [{ json: { injuries: [], fetchError: e.message, injuriesNote: 'Injury lookup failed: ' + e.message, home_bullpen_out: [], away_bullpen_out: [] } }];
}

// Confirmed lineup if the boxscore has posted a batting order yet
// (usually ~1-2 hours before first pitch); otherwise fall back to
// the probable pitchers already captured in MLB Match Fixture.
const fixture = $('MLB Match Fixture').item.json.fixture;

if (!fixture || !fixture.gamePk) {
  return [{ json: { lineupsAvailable: false, lineupsNote: 'No fixture matched — skipping lineup lookup', home_lineup: [], away_lineup: [] } }];
}

const url = 'https://statsapi.mlb.com/api/v1/game/' + fixture.gamePk + '/boxscore';

const extractLineup = teamBox => {
  const order = teamBox?.battingOrder || [];
  const players = teamBox?.players || {};
  return order.map(id => {
    const p = players['ID' + id];
    return p ? (p.person?.fullName + ' (' + (p.position?.abbreviation || '') + ')') : null;
  }).filter(Boolean);
};

try {
  const box = await this.helpers.httpRequest({ url, method: 'GET', json: true });
  const homeLineup = extractLineup(box.teams?.home);
  const awayLineup = extractLineup(box.teams?.away);
  const available = homeLineup.length > 0 && awayLineup.length > 0;

  return [{
    json: {
      lineupsAvailable: available,
      lineupsNote: available
        ? 'Confirmed lineups posted'
        : 'Lineups not yet posted — falling back to probable pitchers only',
      home_lineup: homeLineup,
      away_lineup: awayLineup,
    }
  }];
} catch (e) {
  return [{ json: { lineupsAvailable: false, fetchError: e.message, lineupsNote: 'Lineup lookup failed: ' + e.message, home_lineup: [], away_lineup: [] } }];
}

const fixture = $('MLB Match Fixture').item.json.fixture;

if (!fixture) {
  return [{ json: { home_standing: null, away_standing: null, standingsNote: 'No fixture matched — skipping standings lookup' } }];
}

const season = new Date().getFullYear();
const url = 'https://statsapi.mlb.com/api/v1/standings?leagueId=103,104&season=' + season;

const extract = teamId => {
  for (const rec of (recordsData || [])) {
    const found = (rec.teamRecords || []).find(tr => tr.team?.id === teamId);
    if (found) {
      const home = (found.records?.splitRecords || []).find(s => s.type === 'home');
      const away = (found.records?.splitRecords || []).find(s => s.type === 'away');
      return {
        wins: found.leagueRecord?.wins,
        losses: found.leagueRecord?.losses,
        pct: found.leagueRecord?.pct,
        streak: found.streak?.streakCode,
        divisionRank: found.divisionRank,
        home_record: home ? (home.wins + '-' + home.losses) : 'n/a',
        away_record: away ? (away.wins + '-' + away.losses) : 'n/a',
      };
    }
  }
  return null;
};

let recordsData = [];
try {
  const data = await this.helpers.httpRequest({ url, method: 'GET', json: true });
  recordsData = data.records || [];

  const home_standing = extract(fixture.home_team_id);
  const away_standing = extract(fixture.away_team_id);

  return [{
    json: {
      home_standing,
      away_standing,
      standingsNote: (home_standing && away_standing) ? 'Standings found for both teams' : 'Standings incomplete for one or both teams',
    }
  }];
} catch (e) {
  return [{ json: { home_standing: null, away_standing: null, fetchError: e.message, standingsNote: 'Standings lookup failed: ' + e.message } }];
}

const fixture      = $('MLB Match Fixture').item.json.fixture;
