// --- Pitcher ERA lookups (schedule endpoint doesn't reliably hydrate stats) ---
const season = new Date().getFullYear();
const fetchEra = async pitcherId => {
  if (!pitcherId) return null;
  try {
    const url = 'https://statsapi.mlb.com/api/v1/people/' + pitcherId + '/stats?stats=season&group=pitching&season=' + season;
    const data = await this.helpers.httpRequest({ url, method: 'GET', json: true });
    const split = data.stats?.[0]?.splits?.[0];
    return split ? { era: split.stat?.era, wins: split.stat?.wins, losses: split.stat?.losses, ip: split.stat?.inningsPitched, whip: split.stat?.whip } : null;
  } catch (e) { return null; }
};

let homePitcherStr = 'TBD';
let awayPitcherStr = 'TBD';
let pitcherEdgeStr = 'Not enough data to call a mound edge';

if (fixture) {
  const homeP = fixture.home_probable;
  const awayP = fixture.away_probable;
  const [homeStats, awayStats] = await Promise.all([fetchEra(homeP?.id), fetchEra(awayP?.id)]);

  homePitcherStr = homeP
    ? homeP.fullName + (homeStats ? ' (ERA ' + homeStats.era + ', ' + homeStats.wins + '-' + homeStats.losses + ', WHIP ' + homeStats.whip + ')' : ' (stats unavailable)')
    : 'Not yet announced';
  awayPitcherStr = awayP
    ? awayP.fullName + (awayStats ? ' (ERA ' + awayStats.era + ', ' + awayStats.wins + '-' + awayStats.losses + ', WHIP ' + awayStats.whip + ')' : ' (stats unavailable)')
    : 'Not yet announced';

  if (homeStats?.era && awayStats?.era) {
    const hEra = parseFloat(homeStats.era), aEra = parseFloat(awayStats.era);
    pitcherEdgeStr = hEra < aEra
      ? 'Edge to ' + fixture.home_team_name + ' (' + homeStats.era + ' ERA vs ' + awayStats.era + ')'
      : (aEra < hEra ? 'Edge to ' + fixture.away_team_name + ' (' + awayStats.era + ' ERA vs ' + homeStats.era + ')' : 'Even matchup on ERA');
  }
}

const pitchersStr = fixture
  ? fixture.away_team_name + ': ' + awayPitcherStr + ' | ' + fixture.home_team_name + ': ' + homePitcherStr + ' — ' + pitcherEdgeStr
  : 'Probable pitchers not available';

const injuriesStr = injuries.length
  ? injuries.map(i => i.player + ' (' + i.team + ', ' + i.role + '): ' + i.description).join(' | ')
  : 'No players currently on the injured list for either team';

// --- Bullpen Implications: determine favorite/underdog from the app-provided
// odds text, then apply the three-case rule against each side's reliever count.
let wh = {};
try { wh = $('Webhook').item.json.body ?? $('Webhook').item.json; } catch(e) {}
const oddsText = wh.odds || '';

const teamMatchesSegment = (segment, teamName) => {
  if (!segment || !teamName) return false;
  const s = segment.toLowerCase();
  const words = teamName.toLowerCase().split(/\s+/).filter(w => w.length > 3);
  return words.some(w => s.includes(w));
};

let favorite = null; // 'home' | 'away' | null (unknown)
if (fixture) {
  const segments = oddsText.split('/');
  for (const seg of segments) {
    const oddsMatch = seg.match(/-\d+/); // negative American odds = favorite
    if (!oddsMatch) continue;
    if (teamMatchesSegment(seg, fixture.home_team_name)) { favorite = 'home'; break; }
    if (teamMatchesSegment(seg, fixture.away_team_name)) { favorite = 'away'; break; }
  }
}

const favBullpenOut  = favorite === 'home' ? homeBullpenOut : (favorite === 'away' ? awayBullpenOut : []);
const dogBullpenOut  = favorite === 'home' ? awayBullpenOut : (favorite === 'away' ? homeBullpenOut : []);
const favTeamName    = favorite === 'home' ? fixture?.home_team_name : (favorite === 'away' ? fixture?.away_team_name : null);
const dogTeamName    = favorite === 'home' ? fixture?.away_team_name : (favorite === 'away' ? fixture?.home_team_name : null);

let bullpenFlagStr = 'No bullpen vulnerability detected for either side';
let confidenceAdjustment = 'none';

if (favorite && favBullpenOut.length >= 2 && dogBullpenOut.length >= 2) {
  bullpenFlagStr = '⚠️ BULLPEN VULNERABILITY — ' + favTeamName + ' (' + favBullpenOut.join(', ') + ') AND ⚠️ UNDERDOG BULLPEN CRISIS — ' + dogTeamName + ' (' + dogBullpenOut.join(', ') + '). Both bullpens compromised — higher variance game, lean toward the under on totals, and reduce confidence by one tier.';
  confidenceAdjustment = 'reduce by one tier — both bullpens compromised';
} else if (favorite && favBullpenOut.length >= 2) {
  bullpenFlagStr = '⚠️ BULLPEN VULNERABILITY — ' + favTeamName + ' (' + favBullpenOut.join(', ') + '). Favorite bullpen is thin — boost underdog value +15-20% and factor this into the pick.';
  confidenceAdjustment = 'reduce toward underdog — favorite bullpen vulnerability';
} else if (favorite && dogBullpenOut.length >= 2) {
  bullpenFlagStr = '⚠️ UNDERDOG BULLPEN CRISIS — ' + dogTeamName + ' (' + dogBullpenOut.join(', ') + '). Underdog bullpen is depleted — this reinforces the favorite and reduces upset probability. Public run-differential read on ' + dogTeamName + ' may be overstated if their bullpen can\'t hold leads.';
  confidenceAdjustment = 'reinforces favorite';
} else if (!favorite) {
  bullpenFlagStr = 'Could not determine favorite/underdog from provided odds — bullpen vulnerability check skipped';
}

const lineupsStr = lineupsAvail
  ? (fixture.away_team_name + ' lineup: ' + awayLineup.join(', ') + ' || ' + fixture.home_team_name + ' lineup: ' + homeLineup.join(', '))
  : 'Confirmed lineups not yet posted — using probable pitchers only';

const formStr = (homeStanding && awayStanding && fixture)
  ? fixture.away_team_name + ': ' + awayStanding.wins + '-' + awayStanding.losses + ' (' + awayStanding.pct + '), streak ' + awayStanding.streak + ', away record ' + awayStanding.away_record +
    ' || ' + fixture.home_team_name + ': ' + homeStanding.wins + '-' + homeStanding.losses + ' (' + homeStanding.pct + '), streak ' + homeStanding.streak + ', home record ' + homeStanding.home_record
  : 'Team form not available';

// MLB Stats API returns corporate-naming-rights venue names (e.g.
// "UNIQLO Field at Dodger Stadium") that don't match our lookup table's
// common names. Strip known corporate prefixes/suffixes before lookup,
// with a generic fallback: if "<Sponsor> ... at <Real Name>" and <Real Name>
// is itself a known park, use that — handles future naming-rights changes
// without needing table updates.
const normalizeVenue = (venue) => {
  if (!venue) return '';
  let v = venue.trim();

  v = v.replace(/^UNIQLO Field at /i, '');
  v = v.replace(/^Capital One Arena at /i, '');
  v = v.replace(/\s+presented by.*/i, '');

  const atMatch = v.match(/ at (.+)$/i);
  if (atMatch && PARK_FACTORS[atMatch[1].trim()]) {
    v = atMatch[1].trim();
  }

  return v.trim();
};

const venueName    = fixture?.venue_name;
const normalizedVenue = normalizeVenue(venueName);
const park = normalizedVenue ? PARK_FACTORS[normalizedVenue] : null;
const parkStr = park
  ? normalizedVenue + ' — ' + park.type + ' park. ' + park.notes + '. Factor: ' + park.factor + ' (100 = neutral, >100 hitter friendly, <100 pitcher friendly).'
  : (venueName ? venueName + ' — park factor not in lookup table' : 'Venue unconfirmed');

return [{
  json: {
    fixture,
    fixtureNote,
    pitchers_str:  pitchersStr,
    injuries_str:  injuriesStr,
    lineups_str:   lineupsStr,
    form_str:      formStr,
    park_str:      parkStr,
    bullpen_flag_str: bullpenFlagStr,
    confidence_adjustment: confidenceAdjustment,
  }
}];
